const searchVocabularyDropdown = `-- name: SearchVocabularyDropdown :many

WITH matched_words AS (
  SELECT
    w.id_word,
    w.lemma,
    w.normalized_lemma,
    similarity(w.normalized_lemma, unaccent(lower($1::TEXT))) AS sim
  FROM words w
  WHERE
    $1::TEXT IS NOT NULL 
    AND length(trim($1::TEXT)) > 0 
    AND (
      w.normalized_lemma ILIKE unaccent(lower($1::TEXT)) || '%'
      OR w.search_vector @@ plainto_tsquery('spanish_unaccent', $1::TEXT)
      OR similarity(w.normalized_lemma, unaccent(lower($1::TEXT))) > 0.25
    )
  ORDER BY
    w.normalized_lemma LIKE unaccent(lower($1::TEXT)) || '%' DESC,
    sim DESC,
    w.lemma ASC
  LIMIT 15
),
distinct_words AS (
  SELECT DISTINCT ON (mw.id_word)
    mw.id_word,
    mw.lemma,
    mw.normalized_lemma,
    coalesce(s.short_definition, 'Sin definición corta') AS short_definition,
    coalesce(r.flag_emoji, '🌐') AS flag_emoji,
    coalesce(r.country_code, '') AS country_code,
    mw.sim AS similarity
  FROM matched_words mw
  LEFT JOIN senses s ON s.id_word = mw.id_word AND s.state = 'APPROVED'
  LEFT JOIN regions r ON r.id_region = s.id_region
  ORDER BY
    mw.id_word,
    (r.code = $3::VARCHAR) DESC NULLS LAST,
    s.is_primary DESC
)
SELECT
  dw.id_word,
  dw.lemma,
  dw.short_definition,
  dw.flag_emoji,
  dw.country_code,
  dw.similarity
FROM distinct_words dw
ORDER BY
  dw.normalized_lemma LIKE unaccent(lower($1::TEXT)) || '%' DESC,
  dw.similarity DESC,
  dw.lemma ASC
LIMIT $2::INT
`

type SearchVocabularyDropdownParams struct {
	SearchQuery string `json:"search_query"`
	MaxResults  int32  `json:"max_results"`
	UserDialect string `json:"user_dialect"`
}

type SearchVocabularyDropdownRow struct {
	IDWord          int32   `json:"id_word"`
	Lemma           string  `json:"lemma"`
	ShortDefinition string  `json:"short_definition"`
	FlagEmoji       string  `json:"flag_emoji"`
	CountryCode     string  `json:"country_code"`
	Similarity      float32 `json:"similarity"`
}

// ==============================================================================
// DICCIONARIO Y BÚSQUEDA DIALECTAL (sqlc)
// ==============================================================================
// 1. Búsqueda Rápida para Dropdown / Autocompletado
func (q *Queries) SearchVocabularyDropdown(ctx context.Context, arg SearchVocabularyDropdownParams) ([]SearchVocabularyDropdownRow, error) {
	rows, err := q.db.Query(ctx, searchVocabularyDropdown, arg.SearchQuery, arg.MaxResults, arg.UserDialect)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchVocabularyDropdownRow{}
	for rows.Next() {
		var i SearchVocabularyDropdownRow
		if err := rows.Scan(
			&i.IDWord,
			&i.Lemma,
			&i.ShortDefinition,
			&i.FlagEmoji,
			&i.CountryCode,
			&i.Similarity,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

